from griffe.extensions import Extension
from griffe.objects import Function
from griffe.loader import GriffeLoader


class AppendCheckedExtension(Extension):
    """Extension that appends ' [checked]' to function docstrings."""

    def on_object_loaded(self, obj):
        """Modify docstring when an object is loaded."""
        if isinstance(obj, Function) and obj.docstring and obj.docstring.value:
            obj.docstring.value += " [checked]"


# Aggregate extension the way griffe expects
extensions = [AppendCheckedExtension()]

# Load package through loader with extension enabled
loader = GriffeLoader(extensions=extensions)
package = loader.load("mypkg")

# Verify extension worked
for name, member in package.members.items():
    if isinstance(member, Function) and member.docstring:
        print(f"{name}: {member.docstring.value}")
